from dataclasses import dataclass
from kubernetes import client, config
from langchain_core.tools import tool

config.load_kube_config()
_apps = client.AppsV1Api()


@dataclass
class ScaleResult:
    deployment: str
    namespace: str
    replicas: int


@tool
def scale_deployment_replicas(namespace: str, deployment: str, replicas: int) -> ScaleResult:
    body = {"spec": {"replicas": replicas}}
    updated = _apps.patch_namespaced_deployment_scale(deployment, namespace, body)
    return ScaleResult(deployment=deployment, namespace=namespace, replicas=updated.spec.replicas)

from agents import function_tool
from kubernetes import client, config

config.load_kube_config()
_apps = client.AppsV1Api()


@function_tool
def move_workload_to_node_pool(namespace: str, deployment: str, node_pool: str, pool_label: str = "cloud.google.com/gke-nodepool") -> dict:
    current = _apps.read_namespaced_deployment(deployment, namespace)
    previous = dict(current.spec.template.spec.node_selector or {})
    selector = dict(previous)
    selector[pool_label] = node_pool
    if previous == selector:
        return {"status": "unchanged", "deployment": deployment, "node_selector": selector}
    body = {"spec": {"template": {"spec": {"nodeSelector": selector}}}}
    updated = _apps.patch_namespaced_deployment(deployment, namespace, body)
    return {
        "status": "updated",
        "deployment": updated.metadata.name,
        "namespace": namespace,
        "previous_selector": previous,
        "node_selector": selector,
        "generation": updated.metadata.generation,
    }

from contextlib import contextmanager
from kubernetes import client, config
from langchain_core.tools import tool

config.load_kube_config()
_core = client.CoreV1Api()


@contextmanager
def _cordoned(node_name):
    _core.patch_node(node_name, {"spec": {"unschedulable": True}})
    try:
        yield
    except Exception:
        _core.patch_node(node_name, {"spec": {"unschedulable": False}})
        raise


@tool
def drain_and_delete_node(node_name: str, grace_period_seconds: int = 30) -> str:
    evicted = 0
    with _cordoned(node_name):
        pods = _core.list_pod_for_all_namespaces(field_selector=f"spec.nodeName={node_name}")
        for pod in pods.items:
            owners = pod.metadata.owner_references or []
            if any(o.kind == "DaemonSet" for o in owners):
                continue
            eviction = client.V1Eviction(
                metadata=client.V1ObjectMeta(name=pod.metadata.name, namespace=pod.metadata.namespace),
                delete_options=client.V1DeleteOptions(grace_period_seconds=grace_period_seconds),
            )
            _core.create_namespaced_pod_eviction(pod.metadata.name, pod.metadata.namespace, eviction)
            evicted += 1
        _core.delete_node(node_name)
    return f"Evicted {evicted} pods and deleted node {node_name}"
